; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI, 3 ADM-3A, 4 Televideo (CP/M)
NTC_TERM_RT	equ 0		; 1: the program calls StdIO.SetTerminal (the terminal is chosen while it runs)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 1		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_WINPAGED	equ 0		; 1 = page 0 code may sit under the window (Option Memory Paged, not Reserved): the Memory class never hands out page 1 (main RAM's own #4000-#7FFF) when the code reaches past #4000
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_ISLN	equ 1		; interrupt classes (Option Class Interrupt): the slots ntc_isl has (8 bytes each)
NTC_INTS	equ 1		; 0 = the platform never lets interrupts in (;@ints 0: ntc_xn's safe point has no ei)
NTC_PLATRSV	equ 0		; 1 = the platform's fixed areas (;@reserved) are Reserved in the memory map: the build goes round them (the old top-of-RAM asserts are off)
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			jr ntc_start2
ntc_bk_sp:		dw 0			; #0042: main RAM's SP while a bank runs
ntc_bk_out:
			out (c), c		; #0044: BC = the other side's RAM setting
			jp ntc_bk_land		; #0046: main RAM switched in
ntc_bk_land:
			ld sp, (ntc_bk_sp)
			ret				; to where main RAM handed over
			ASSERT ntc_bk_out == #0044, "the bank switch must be at #0044"
ntc_start2:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			di				; (KL ROM SELECT lets interrupts in again)
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 8: Print "1 started"
			dw kw_printstrvar, str0
			dw kw_printnl

			; main.bas 9: Wait
			dw p_wait_c

			; main.bas 10: Print "2 Capability LOAD"; FileSystem.Capability("LOAD"); " SAVE"; FileSystem.Capability("SAVE")
			dw fn_filesystem_capability, str1, var_filesystem_capability_capability
			dw kw_printstrvar, str2
			dw kw_printint, var_filesystem_capability_capability
			dw fn_filesystem_capability, str3, var_filesystem_capability_capability
			dw kw_printstrvar, str4
			dw kw_printint, var_filesystem_capability_capability
			dw kw_printnl

			; main.bas 11: Wait
			dw p_wait_c

			; main.bas 12: Print "3 Devices: "; FileSystem.Devices()
			dw fn_filesystem_devices, var_filesystem_devices_devices
			dw kw_printstrvar, str5
			dw kw_printstrvar, var_filesystem_devices_devices
			dw kw_printnl

			; main.bas 13: Wait
			dw p_wait_c

			; main.bas 14: Print "4 CurrentDevice: "; FileSystem.CurrentDevice(); "  Volume: "; FileSystem.CurrentVolume()
			dw fn_filesystem_currentdevice, var_filesystem_currentdevice_currentdevice
			dw kw_printstrvar, str6
			dw kw_printstrvar, var_filesystem_currentdevice_currentdevice
			dw fn_filesystem_currentvolume, var_filesystem_currentvolume_currentvolume
			dw kw_printstrvar, str7
			dw kw_printstrvar, var_filesystem_currentvolume_currentvolume
			dw kw_printnl

			; main.bas 15: Wait
			dw p_wait_c

			; main.bas 16: For i = 0 To 9 : a(i) = 1000 - i * 50 : Next
			dw kw_ztov, var_i
for1_t:
			dw kw_mulvl, var_i, 50, tmp2
			dw kw_sublv, 1000, tmp2, tmp1
			dw kw_aset, arr_a, var_i, tmp1
			dw kw_next1l_n, var_i, 9, for1_t
for1_e:

			; main.bas 17: Print "5 Save STEP.DAT..."
			dw kw_printstrvar, str8
			dw kw_printnl

			; main.bas 18: Wait
			dw p_wait_c

			; main.bas 19: r = FileSystem.Save("STEP.DAT", VarPtr(a), 20)
			dw fn_filesystem_save, str9, vp_arr_a, lit_20, var_r

			; main.bas 20: Print "  Save gave"; r
			dw kw_printstrvar, str10
			dw kw_printint, var_r
			dw kw_printnl

			; main.bas 21: Wait
			dw p_wait_c

			; main.bas 22: Print "6 Load STEP.DAT..."
			dw kw_printstrvar, str11
			dw kw_printnl

			; main.bas 23: Wait
			dw p_wait_c

			; main.bas 24: r = FileSystem.Load("STEP.DAT", VarPtr(b), 20)
			dw fn_filesystem_load, str9, vp_arr_b, lit_20, var_r

			; main.bas 25: Print "  Load gave"; r; ", "; b(0); " ... "; b(9)
			dw kw_printstrvar, str12
			dw kw_printint, var_r
			dw kw_printstrvar, str13
			dw kw_printint, arr_b
			dw kw_printstrvar, str14
			dw kw_printint, arr_b+18
			dw kw_printnl

			; main.bas 26: Print "7 done"
			dw kw_printstrvar, str15
			dw kw_printnl

			; main.bas 27: End
			dw kw_printnl0
			dw kw_printstrvar, str16
			dw kw_waitkey
			dw kw_stop

; ============================================================
; sub wait (normal mode)
; ============================================================

p_wait:

			; main.bas 30: Print "  (press a key)"
			dw kw_printstrvar, str17
			dw kw_printnl

			; main.bas 31: Do While Inkey <> 0 : Loop
do2_t:
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do2_e
			dw do2_t_go
do2_e:

			; main.bas 32: Do : Frame : Loop Until Inkey <> 0
do3_t:
			dw kw_frame
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do3_t
do3_e:
			dw p_wait_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do2_t_go:			ld sp, do2_t
			jp ntc_xn

p_wait_c:		; call wait (normal)
			ld (p_wait_rs), sp
			ld sp, p_wait
			jp ntc_xn
p_wait_r:		; end of wait
			ld sp, (p_wait_rs)
			jp ntc_xn

; ============================================================
; Inline assembly (#asm ... #endasm)
; ============================================================

fn_filesystem_capability:		; function capability (asm keyword), FileSystem.cls line 38
            pop hl		; FileSystem.cls 39
            pop de		; FileSystem.cls 40
            ld bc, fn_filesystem_capability_caps		; FileSystem.cls 41
            jp ntc_capfind		; FileSystem.cls 42
fn_filesystem_capability_caps:       db "LOAD", 0		; FileSystem.cls 43
            dw -1		; FileSystem.cls 44
            db "SAVE", 0		; FileSystem.cls 45
            dw -1		; FileSystem.cls 46
            db "SEQUENTIAL", 0		; FileSystem.cls 47
            dw -1		; FileSystem.cls 48
            db "DEVICES", 0		; FileSystem.cls 49
            dw -1		; FileSystem.cls 50
            db "VOLUMES", 0		; FileSystem.cls 51
            dw -1		; FileSystem.cls 52
            db "ROMDISC", 0		; FileSystem.cls 53
            dw 0		; FileSystem.cls 54
            db "MAXOPEN", 0		; FileSystem.cls 55
            dw 1		; FileSystem.cls 56
            db 0		; FileSystem.cls 57
			ret			; end of #asm

fn_filesystem_load:		; function load (asm keyword), FileSystem.cls line 64
            pop hl		; FileSystem.cls 65
            ld (fs_a1), hl		; FileSystem.cls 66
            pop hl		; FileSystem.cls 67
            ld e, (hl)		; FileSystem.cls 68
            inc hl		; FileSystem.cls 69
            ld d, (hl)		; FileSystem.cls 70
            ld (fs_a2), de		; FileSystem.cls 71
            pop hl		; FileSystem.cls 72
            ld e, (hl)		; FileSystem.cls 73
            inc hl		; FileSystem.cls 74
            ld d, (hl)		; FileSystem.cls 75
            ld (fs_a3), de		; FileSystem.cls 76
            pop hl		; FileSystem.cls 77
            ld (fs_res), hl		; FileSystem.cls 78
            ld hl, fs_load		; FileSystem.cls 79
            jp fs_go		; FileSystem.cls 80
			ret			; end of #asm

fn_filesystem_save:		; function save (asm keyword), FileSystem.cls line 86
            pop hl		; FileSystem.cls 87
            ld (fs_a1), hl		; FileSystem.cls 88
            pop hl		; FileSystem.cls 89
            ld e, (hl)		; FileSystem.cls 90
            inc hl		; FileSystem.cls 91
            ld d, (hl)		; FileSystem.cls 92
            ld (fs_a2), de		; FileSystem.cls 93
            pop hl		; FileSystem.cls 94
            ld e, (hl)		; FileSystem.cls 95
            inc hl		; FileSystem.cls 96
            ld d, (hl)		; FileSystem.cls 97
            ld (fs_a3), de		; FileSystem.cls 98
            pop hl		; FileSystem.cls 99
            ld (fs_res), hl		; FileSystem.cls 100
            ld hl, fs_save		; FileSystem.cls 101
            jp fs_go		; FileSystem.cls 102
			ret			; end of #asm

fn_filesystem_devices:		; function devices (asm keyword), FileSystem.cls line 298
            pop hl		; FileSystem.cls 299
            ld (fs_res), hl		; FileSystem.cls 300
            ld hl, fs_devices		; FileSystem.cls 301
            jp fs_go0		; FileSystem.cls 302
			ret			; end of #asm

fn_filesystem_currentdevice:		; function currentdevice (asm keyword), FileSystem.cls line 308
            pop hl		; FileSystem.cls 309
            ld (fs_res), hl		; FileSystem.cls 310
            ld hl, fs_curdev		; FileSystem.cls 311
            jp fs_go0		; FileSystem.cls 312
			ret			; end of #asm

fn_filesystem_currentvolume:		; function currentvolume (asm keyword), FileSystem.cls line 341
            pop hl		; FileSystem.cls 342
            ld (fs_res), hl		; FileSystem.cls 343
            ld hl, fs_curvol		; FileSystem.cls 344
            jp fs_go0		; FileSystem.cls 345
			ret			; end of #asm


; ============================================================
; Variables
; ============================================================

var_filesystem_capability_capability:			dw 0
			db 255			; capacity
var_filesystem_devices_devices:			ds 256
			db 255			; capacity
var_filesystem_currentdevice_currentdevice:			ds 256
			db 255			; capacity
var_filesystem_currentvolume_currentvolume:			ds 256
var_i:			dw 0
var_r:			dw 0
p_wait_rs:			dw 0
tmp0:			dw 0
tmp1:			dw 0
tmp2:			dw 0

; numbers passed by address (read only)
vp_arr_a:			dw arr_a
lit_20:			dw 20
vp_arr_b:			dw arr_b
llit_m1:			dw 65535, 65535

; ============================================================
; Strings
; ============================================================

str0:			db "1 started", 0
str1:			db "LOAD", 0
str2:			db "2 Capability LOAD", 0
str3:			db "SAVE", 0
str4:			db " SAVE", 0
str5:			db "3 Devices: ", 0
str6:			db "4 CurrentDevice: ", 0
str7:			db "  Volume: ", 0
str8:			db "5 Save STEP.DAT...", 0
str9:			db "STEP.DAT", 0
str10:			db "  Save gave", 0
str11:			db "6 Load STEP.DAT...", 0
str12:			db "  Load gave", 0
str13:			db ", ", 0
str14:			db " ... ", 0
str15:			db "7 done", 0
str16:			db "Press a key to end", 0
str17:			db "  (press a key)", 0
str18:			db 0

; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPCFW (NTCFW.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_goto_iffalse_n:	jp 11
kw_next1l_n:	jp 31
kw_ztov:		jp 49
kw_sublv:	jp 56
kw_mulvl:	jp 61
kw_cpnevl:	jp 98
kw_aset:		jp 112
kw_printstrvar:	jp 129
kw_printint:	jp 131
kw_printnl0:	jp 134
kw_printnl:	jp 138
kw_inkey:	jp 144
kw_frame:	jp 152
ntc_capfind:	jp 242
kw_bssinit:	jp 288
fs_go0:		jp 315
fs_go:		jp 316
fs_devices:	jp 317
fs_curdev:	jp 318
fs_curvol:	jp 321
fs_load:		jp 324
fs_save:		jp 325
kw_waitkey:	jp 348
NTC_RJ_N	equ 25		; entries
fs_a1	equ #891B		; ROM data
fs_a2	equ #891D		; ROM data
fs_a3	equ #891F		; ROM data
fs_res	equ #8921		; ROM data
ntc_csp	equ #8800		; ROM data
ntc_nmode	equ #8807		; ROM data
ntc_v_free	equ #894E		; ROM data
ntc_v_romen	equ #8954		; ROM data
ntc_v_romold	equ #8956		; ROM data
ntc_v_stamp	equ #8952		; ROM data
ntc_v_start	equ #8950		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)


; the start code (Library: ROM): run once, then the arrays go over it
ntc_rj_drop:
; the start: find the ROM set in slots 0 - 31 (its main ROM, then the others with the same
; stamp), have the main one patch the jump block. NC = ready; C = not there / too old
; (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			xor a
			ld (ntc_rj_want), a
			call ntc_rj_scan		; the main ROM
			jp c, ntc_rj_nf
			ld (ntc_rj_slots), a
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, 1
ntc_rj_more:				; the other ROMs of the set
			ld (ntc_rj_want), a
			ld hl, ntc_rj_n
			cp (hl)
			jr nc, ntc_rj_all
			call ntc_rj_scan
			jp c, ntc_rj_part
			ld b, a
			ld a, (ntc_rj_want)
			ld e, a
			ld d, 0
			ld hl, ntc_rj_slots
			add hl, de
			ld (hl), b
			inc a
			jr ntc_rj_more
ntc_rj_all:
			ld a, (ntc_rj_slots)
			ld c, a
			call #B90F		; KL ROM SELECT: the main ROM
			di					; (KL ROM SELECT lets interrupts in)
			ld a, (ntc_rj_slots)	; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
			ld de, ntc_rj_slots
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot, DE = slots; C: DE = a number it hasn't got
			jp c, ntc_rj_lacks
			IF (ntc_bss >= 32768) && (ntc_bssfrom <= 16384)	; fwdref-ok
			ld hl, ntc_bssfrom		; (the end of the program - or this start code, which tables may go over)
			ELSE
			ld hl, ntc_free
			ENDIF
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, 0
			ld (ntc_v_stamp), hl
			ld a, 0
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
; ntc_rj_scan - a ROM of the set: ROM ntc_rj_want (0 = the main one, any stamp; the others
; with the main one's stamp). NC: A = its slot, HL = past its block's count byte (the main
; one: at its patcher), it is selected. C: not there
ntc_rj_scan:
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; DE = its set's stamp
			inc hl
			ld a, (ntc_rj_want)
			cp (hl)				; its place in the set
			jr nz, ntc_rj_skip
			or a
			jr z, ntc_rj_got
			push hl
			ld hl, (ntc_rj_set)
			or a
			sbc hl, de
			pop hl
			jr nz, ntc_rj_skip		; another build's
ntc_rj_got:
			ld (ntc_rj_set), de
			inc hl
			ld a, (hl)
			ld (ntc_rj_n), a		; ROMs in the set
			inc hl
			ld a, c
			or a				; NC
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			scf					; C: not there
			ret
ntc_rj_nf:
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_part:				; a ROM of the set is missing: its number (1 = the main one)
			ld a, (ntc_rj_want)
			inc a
			ld e, a
			ld d, 0
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tpt
			jr ntc_rj_fnum
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fnum:
			ld a, 1
			ld (ntc_rj_pn), a		; the number after the message
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld a, (ntc_rj_pn)
			or a
			jr z, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
ntc_rj_num:		dw 0
ntc_rj_pn:		db 0			; 1 = a number goes after the message
ntc_rj_want:	db 0			; the ROM of the set looked for
ntc_rj_n:		db 1			; ROMs in the set
ntc_rj_set:		dw 0			; the set's stamp
ntc_rj_slots:	ds 8			; each ROM's slot, the main one first
ntc_rj_sig:		db "NTC", 2, "CPCFW", 0	; the ROMs' NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "ROM NTC CPCFW (NTCFW.ROM) not found", 0
ntc_rj_tlk:		db "ROM NTC CPCFW too old: no routine #", 0
ntc_rj_tpt:		db "ROM NTCFW<n>.ROM not found: n = #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0
ntc_rj_dropend:
ntc_end:				; the end of the program (and of its file)
			DISPLAY "NTC memory: program ", /H, ntc_start, "-", /H, ntc_end - 1, " arrays ", /H, ntc_bss, "-", /H, ntc_free - 1, " stack the caller's"
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
			IF ntc_rj_dropend == ntc_end	; fwdref-ok
ntc_bssfrom	equ ntc_rj_drop		; the arrays over the start code (it has run)
			ELSE
ntc_bssfrom	equ ntc_end
			ENDIF
ntc_bss		equ ntc_bssfrom
arr_a		equ ntc_bss + 0		; 20 bytes
arr_b		equ ntc_bss + 20		; 20 bytes
ntc_bss_size	equ 40
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
